 const chatMode=currentPath()==='/swarm-intelligence/chat';
 if(chatMode){if(!selectedChatAgents.size||selectedChatAgents.size>3){showToast('Choose one to three specialists before starting.',true);return;}automaticRouting=false;manualAgents=new Set(selectedChatAgents);webSearch=selectedChatAgents.has('search')||selectedChatAgents.has('research');}
 const firstChatMessage=chatMode&&!chatMessages.some(message=>message.role==='user');const intake=firstChatMessage?collectChatIntake():'';let userMessage=taskInput.value.trim();if(!userMessage&&firstChatMessage&&intake&&hasMeaningfulChatIntake())userMessage='Use the specialist requirements below as the task.';if(!userMessage){showToast(chatMode?'Type a task or fill in a specialist requirement.':'Write a message for your selected specialists.',true);if(chatMode&&!hasMeaningfulChatIntake())workspaceContent?.querySelector('[data-intake-key]')?.focus();else taskInput.focus();return;}let task=userMessage;
 if(chatMode&&chatMessages.length){const prior=chatMessages.slice(-8).map(message=>`${message.role==='user'?'User':'ODDI'}:\n${message.text.slice(0,900)}`).join('\n\n').slice(-3600);task=`Previous messages in this Swarm chat (context only; follow the latest request):\n${prior}\n\nLatest user message:\n${userMessage}`;}
