 if(writingOptions)task=[task,'',`Writing preferences:`,`Operation: ${writingOptions.operation}`,`Content type: ${writingOptions.deliverable}`,`Tone: ${writingOptions.tone}`,`Length: ${writingOptions.length}`,writingOptions.audience?`Audience: ${writingOptions.audience}`:'Audience: use the request context only'].join('\n');
 const runOutputFormat=preferences.output_format||'answer';if(!automaticRouting&&!manualAgents.size){showToast('Choose specialists before starting.',true);return;}
 const selectedForRun=chatMode?[...selectedChatAgents]:[...manualAgents],payload=new FormData();payload.append('task',task);payload.append('agents',JSON.stringify(automaticRouting?['auto']:selectedForRun));payload.append('auto_route',String(chatMode?false:automaticRouting));if(chatMode)payload.append('selection_mode','manual_chat');payload.append('web_search',String(webSearch));payload.append('output_format',runOutputFormat);payload.append('preferred_output_format',preferences.output_format||'answer');payload.append('idempotency_key',window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`);attachments.forEach(file=>payload.append('files',file));
 isSubmitting=true;sendButton.disabled=true;const intakeSend=document.getElementById('swarmIntakeSend');if(intakeSend)intakeSend.disabled=true;progress.hidden=false;progressLabel.textContent=chatMode?'Starting the specialists you selected':automaticRouting?'Central Intelligence is planning the specialists':`Queueing ${selectedForRun.map(agentName).join(', ')}`;
